  "JOUR3_THE_SPACE_BETWEEN_US__3HRS_": {
    html: "It will be an amazing ceremony to create cohesion in the group, and will allow deeper vulnerability. It would be nice if this was put on during a time that less it happening and more people will gather here. Also a desire for spaciousness in sound so that there are no other loud workshops during this time so there is a felt sense of peace. Space requirements: Two adjacent circles in a large divided space, capable of reuniting into one larger ceremonial space. Full sound system required. Privacy essential. Each room will need cushions for each person to sit on within circle. <br>Mattresses, cushions, palo santo/sauge",
    text: "It will be an amazing ceremony to create cohesion in the group, and will allow deeper vulnerability. It would be nice if this was put on during a time that less it happening and more people will gather here. Also a desire for spaciousness in sound so that there are no other loud workshops during this time so there is a felt sense of peace. Space requirements: Two adjacent circles in a large divided space, capable of reuniting into one larger ceremonial space. Full sound system required. Privacy essential. Each room will need cushions for each person to sit on within circle. \nMattresses, cushions, palo santo/sauge",
    validatedByFac: false,
    prepDuration: 45,
    updatedAt: "2026-08-18 23:48"
  },

